"""RS1 R2 -> thinking-ON training set. Generated by kaggle/rftset/build.sh (edit rft_core.py, not this)."""
import pathlib, re
# ------------------------------------------------------------------ analysis/format_drift.py (classify)
SCHEMA = {  # tool -> (required, optional), from swegemma 0.2.7 tool signatures
    "run_command": ({"command"}, set()),
    "read_file": ({"filepath"}, {"start_line", "end_line"}),
    "write_file": ({"filepath", "content"}, set()),
    "edit_file": ({"filepath", "old_string", "new_string"}, {"allow_multiple"}),
    "submit_patch": (set(), set()),
    "get_status": (set(), set()),
    "get_code_neighbors": ({"node"}, {"edge_type", "max_neighbors"}),
    "search_similar_code": ({"query"}, {"k"}),
    "get_code_subgraph": ({"nodes"}, set()),
    "load_skill": ({"skill_name"}, set()),
    "list_skills": (set(), set()),
    "run_skill_script": ({"skill_name", "file_path"}, {"args"}),
}
IDENT = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")


def classify(name, args):
    req, opt = SCHEMA.get(name, (None, None))
    if req is None:
        return {"unknown_tool"}
    cls = set()
    if not isinstance(args, dict):
        return {"non_dict_args"}
    for k, v in args.items():
        bare = k.strip("\"' ")
        if not IDENT.match(k):
            cls.add("quoted_key" if IDENT.match(bare) else "code_key")
        elif k not in req | opt:
            cls.add("extra_key")
        if isinstance(v, str) and len(v) >= 2 and v[0] == v[-1] and v[0] in "\"'" and "\n" not in v:
            cls.add("quoted_value")
    keys = {k.strip("\"' ") for k in args}
    if req - set(args):
        cls.add("missing_req")
    return cls


import glob
import json
import pathlib
import statistics
import tarfile

import jinja2
from jinja2.sandbox import ImmutableSandboxedEnvironment
from tokenizers import Tokenizer

OUT = pathlib.Path("/kaggle/working/rftset")
WORK = pathlib.Path("/tmp/rftset")
MAX_WINDOW = 8192
AGENT = "swe_noedit_agent"
ANALYZER = {"name": "code_analyzer_agent",
            "description": "Analyzes repository source files and symbol graphs to locate root causes.",
            "parameters": {"type": "object", "properties": {"request": {"type": "string"}}, "required": ["request"]}}


# ------------------------------------------------------------------ Gemma-4 template + tokenizer (no transformers)
class Gemma:
    def __init__(self, model_dir):
        env = ImmutableSandboxedEnvironment(trim_blocks=True, lstrip_blocks=True, extensions=["jinja2.ext.loopcontrols"])
        env.filters["tojson"] = lambda x, indent=None, ensure_ascii=False, sort_keys=False: json.dumps(
            x, indent=indent, ensure_ascii=ensure_ascii, sort_keys=sort_keys)

        def _raise(m):
            raise jinja2.exceptions.TemplateError(m)
        env.globals["raise_exception"] = _raise
        d = pathlib.Path(model_dir)
        tpl = (d / "chat_template.jinja").read_text() if (d / "chat_template.jinja").exists() else \
            json.loads((d / "tokenizer_config.json").read_text())["chat_template"]
        self.tpl = env.from_string(tpl)
        self.tok = Tokenizer.from_file(str(d / "tokenizer.json"))

    def render(self, messages, tools, gen=False):
        return self.tpl.render(messages=messages, tools=tools, add_generation_prompt=gen, enable_thinking=True,
                               bos_token="<bos>", eos_token="<eos>")

    def n(self, text):
        return len(self.tok.encode(text, add_special_tokens=False).ids)


def model_spans(text):
    """char spans the model wrote (thinking, tool calls, text) inside model turns, minus embedded tool responses."""
    spans, i = [], 0
    while True:
        a = text.find("<|turn>model\n", i)
        if a < 0:
            return spans
        a += len("<|turn>model\n")
        b = text.find("<turn|>", a)
        b = len(text) if b < 0 else b + len("<turn|>")
        j = a
        while j < b:
            r = text.find("<|tool_response>", j, b)
            if r < 0:
                spans.append([j, b])
                break
            if r > j:
                spans.append([j, r])
            e = text.find("<tool_response|>", r, b)
            j = b if e < 0 else e + len("<tool_response|>")
        i = b


# ------------------------------------------------------------------ trajectories
def episode(trace, system):
    """-> (messages, per-step logged prompt_tokens [None for steps without an LLM call], drifted call count)."""
    steps = trace["steps"]
    task = next(s["message"] for s in steps if s.get("source") == "user")
    msgs, logged, drift = [{"role": "system", "content": system}, {"role": "user", "content": task}], [], 0
    for s in steps:
        if s.get("source") != "agent" or (s.get("extra") or {}).get("author", AGENT) != AGENT:
            continue
        logged.append(((s.get("metrics") or {}).get("prompt_tokens"), len(msgs)))
        tcs = s.get("tool_calls") or []
        if not tcs:
            msgs.append({"role": "assistant", "content": s.get("message") or ""})
            continue
        for t in tcs:
            if t["function_name"] != ANALYZER["name"] and classify(t["function_name"], t.get("arguments")):
                drift += 1
        msgs.append({"role": "assistant", "reasoning_content": s.get("message") or "",
                     "tool_calls": [{"id": t["tool_call_id"], "type": "function",
                                     "function": {"name": t["function_name"], "arguments": t.get("arguments") or {}}}
                                    for t in tcs]})
        obs = s.get("observation") or {}
        for k, res in enumerate(obs.get("results") or ([obs] if obs else [])):
            c = res.get("content")
            msgs.append({"role": "tool", "tool_call_id": tcs[min(k, len(tcs) - 1)]["tool_call_id"],
                         "content": c if isinstance(c, str) else json.dumps(c)})
    return msgs, logged, drift


def gaps(g, msgs, logged, tools):
    """logged - rendered prompt tokens at each step that has a logged count."""
    return [lp - g.n(g.render(msgs[:k], tools, gen=True)) for lp, k in logged if lp]


def windows(g, msgs, tools):
    """<= MAX_WINDOW windows at assistant-step boundaries: head (system + task) + consecutive steps (render_atif)."""
    head, steps, cur = msgs[:2], [], []
    for m in msgs[2:]:
        if m["role"] == "assistant" and cur:
            steps.append(cur)
            cur = []
        cur.append(m)
    if cur:
        steps.append(cur)
    out, cur = [], []
    for st in steps:
        if cur and g.n(g.render(head + [m for s in cur + [st] for m in s], tools)) > MAX_WINDOW:
            out.append(head + [m for s in cur for m in s])
            cur = [st]
        else:
            cur.append(st)
    if cur:
        out.append(head + [m for s in cur for m in s])
    return out


def lib_of(i):
    return i.split("_", 1)[1].rsplit("_", 1)[0]


def main(submission_dir, tools_base):
    OUT.mkdir(parents=True, exist_ok=True)
    WORK.mkdir(parents=True, exist_ok=True)
    model_dir = next(pathlib.Path(p).parent for p in sorted(glob.glob("/kaggle/input/**/tokenizer.json", recursive=True))
                     if "w4a16" in p.lower())
    g = Gemma(model_dir)
    system = (submission_dir / "prompts" / "system.md").read_text()
    meta = {}
    for p in glob.glob("/kaggle/input/**/task_meta.jsonl", recursive=True):
        meta.update({json.loads(l)["id"]: json.loads(l) for l in open(p)})
    shards = {}
    for tgz in sorted(glob.glob("/kaggle/input/**/eval_rollout_s*.tgz", recursive=True)):
        name = pathlib.Path(tgz).stem.replace("eval_", "")
        if name in shards:
            continue
        with tarfile.open(tgz) as tf:
            tf.extractall(WORK, filter="data")
        root = WORK / f"eval_{name}" / "rep0"
        shards[name] = root
        print("shard", name, root, flush=True)
    assert len(shards) == 2, f"expected 2 R2 shards, got {sorted(shards)}"

    per_task, traces = {}, {}
    for name, root in shards.items():
        for l in open(root / "analysis" / "per_task.jsonl"):
            r = json.loads(l)
            per_task[r["instance_id"]] = r
        for p in (root / "merged" / "traces").glob("trace_*.json"):
            traces[p.stem.replace("trace_", "")] = p
    resolved = sorted(i for i, r in per_task.items() if r.get("resolved"))
    print(f"{len(per_task)} tasks, {len(resolved)} resolved, {len(traces)} traces", flush=True)

    # fidelity: pick the prefix variant (tool list / identity line) whose rendered prompt matches vLLM's counts
    ident = f'You are an agent. Your internal name is "{AGENT}".'
    variants = {
        "tools": (system, tools_base),
        "tools+analyzer": (system, tools_base + [{"type": "function", "function": ANALYZER}]),
        "tools+analyzer+identity": (ident + "\n\n" + system, tools_base + [{"type": "function", "function": ANALYZER}]),
    }
    probe = resolved[:: max(1, len(resolved) // 12)][:12]
    fid = {}
    for vn, (sysv, tl) in variants.items():
        gs = []
        for i in probe:
            msgs, logged, _ = episode(json.loads(traces[i].read_text()), sysv)
            gs += gaps(g, msgs, logged, tl)
        fid[vn] = {"median": statistics.median(gs), "min": min(gs), "max": max(gs), "n": len(gs)}
    best = min(fid, key=lambda v: abs(fid[v]["median"]))
    sysv, tools = variants[best]
    print("FIDELITY", json.dumps(fid), "->", best, flush=True)

    rows, n_win, stats = [], 0, []
    with open(OUT / "episodes.jsonl", "w") as fe, open(OUT / "windows_8k.jsonl", "w") as fw:
        for i in resolved:
            pt, m = per_task[i], meta.get(i, {})
            msgs, logged, drift = episode(json.loads(traces[i].read_text()), sysv)
            text = g.render(msgs, tools)
            tags = {"stray_files": pt.get("stray_files_in_patch") or [], "tests_after_last_edit": pt.get("tests_after_last_edit") or 0,
                    "tool_calls": pt.get("n_tool_calls"), "analyzer_calls": pt.get("analyzer_calls") or 0,
                    "drifted_calls": drift, "max_prompt_tokens": pt.get("max_prompt_tokens"),
                    "duration_s": pt.get("duration_s"), "src": i[:3], "lib": lib_of(i), "kind": m.get("kind"),
                    "ops": m.get("ops", [])}
            # core = what an RFT run should train on by default: no stray files, no drift, main agent only
            tags["core"] = not tags["stray_files"] and not drift and not tags["analyzer_calls"]
            g_last = gaps(g, msgs, logged[-1:], tools) if logged and logged[-1][0] else []
            nt = g.n(text)
            row = {"id": i, **tags, "n_tokens": nt, "gap_last_step": g_last[0] if g_last else None,
                   "messages": msgs, "text": text, "train_spans": model_spans(text)}
            fe.write(json.dumps(row) + "\n")
            for w, wm in enumerate(windows(g, msgs, tools)):
                wt = g.render(wm, tools)
                fw.write(json.dumps({"id": i, "role": AGENT, "window": w, "core": tags["core"], "text": wt,
                                     "train_spans": model_spans(wt), "n_tokens": g.n(wt)}) + "\n")
                n_win += 1
            rows.append({k: v for k, v in row.items() if k not in ("messages", "text", "train_spans")})
            stats.append(nt)
    core = [r for r in rows if r["core"]]

    def count(rs, key):
        out = {}
        for r in rs:
            for v in (r[key] if isinstance(r[key], list) else [r[key]]):
                out[v] = out.get(v, 0) + 1
        return dict(sorted(out.items(), key=lambda kv: -kv[1]))
    report = {
        "fidelity": fid, "variant": best, "resolved": len(rows), "core": len(core),
        "dropped_from_core": {"stray_files": sum(bool(r["stray_files"]) for r in rows),
                              "drift": sum(r["drifted_calls"] > 0 for r in rows),
                              "analyzer": sum(r["analyzer_calls"] > 0 for r in rows)},
        "tested_after_last_edit": sum(r["tests_after_last_edit"] > 0 for r in rows),
        "episode_tokens": {"median": statistics.median(stats), "p90": sorted(stats)[int(0.9 * len(stats))], "max": max(stats)},
        "over_8k": sum(t > MAX_WINDOW for t in stats), "windows_8k": n_win,
        "tool_calls_median": statistics.median(r["tool_calls"] for r in rows),
        "core_by": {k: count(core, k) for k in ("src", "kind", "lib")},
        "gap_last_step": {"median": statistics.median(x for x in (r["gap_last_step"] for r in rows) if x is not None)},
        "rows": rows,
    }
    (OUT / "rftset_report.json").write_text(json.dumps(report, indent=1))
    print("RS1 REPORT", json.dumps({k: v for k, v in report.items() if k != "rows"}), flush=True)

# ------------------------------------------------------------------ embedded v14 submission bits
SUB = pathlib.Path('/tmp/rftset_sub'); (SUB / 'prompts').mkdir(parents=True, exist_ok=True)
(SUB / 'prompts' / 'system.md').write_text('You are an expert autonomous software engineer assigned to resolve an issue in a repository efficiently and decisively.\n\n## Core Objective: Fast, Minimal, and Precise Fixes\nAim to understand, resolve, and submit the fix in the minimum number of tool calls (under 8–10 turns). Move directly from the problem statement to the relevant files, apply the solution, verify with a targeted test, and submit.\n\n## Workflow\n\n### 1. Identify Target Files Immediately\n- Extract filenames, functions, classes, CLI subcommands, or error messages directly from the problem statement.\n- Read only the specific target files and lines with `run_command` using `grep -n PATTERN path` and `sed -n \'START,ENDp\' path` (read at most ~80 lines at a time), or search tools. Do not wander across unrelated files.\n- If the problem statement does not provide explicit file paths, use `search_similar_code` with keywords from the error message to locate relevant files efficiently, rather than running `find` or `grep` across the entire repo.\n\n### 2. Implement the Solution Directly\n- Apply the minimal necessary fix or feature directly to the source files. Edit by replacing an exact snippet with a short Python script via `run_command` (copy the old lines exactly as `sed -n` printed them):\n  ```\n  python3 - <<\'PYEOF\'\n  import pathlib\n  p = pathlib.Path("path/to/file.py")\n  s = p.read_text()\n  old = """<exact old lines>"""\n  new = """<replacement lines>"""\n  assert s.count(old) == 1, s.count(old)\n  p.write_text(s.replace(old, new))\n  PYEOF\n  ```\n  If the assert fails, re-read the lines with `sed -n` and retry with a smaller exact snippet. For short files you may rewrite the whole file with `write_file`.\n- Strictly adhere to specified error strings, exception types, HTTP status codes, and API signatures.\n- For documentation code tasks (e.g. FastAPI), edit executable code under `docs_src/`.\n\n### 3. Run Targeted Tests Only (Existing Tests May Be Broken)\n- **Run ONLY Targeted Tests**: Run only the specific test file or test method directly verifying the bug or feature you modified (e.g. `pytest tests/test_target.py -k test_feature` or `python3 -m unittest tests.test_target`).\n- **Be Aware That Existing Tests May Be Broken**: Many repositories contain pre-existing test breakages, missing test data fixtures (e.g. `/test_data`), or environment import errors unrelated to your task.\n- **Do NOT Attempt to Fix Existing Tests**: If an existing test fails due to pre-existing repository issues or missing fixtures, IGNORE IT. Never spend turns attempting to repair pre-existing test failures, create test stubs, or alter test code.\n- **STRICT RULE: NEVER Run Bare Pytest or Full-Repo Sweeps**: NEVER run bare `pytest`, `pytest .`, `python3 -m unittest discover`, or full-repo test suites without specifying a target file. Full test suites take several minutes, cause catastrophic timeouts, and exhaust your turn and time budgets.\n- If you need to locate the test file, find it explicitly with `find tests -name "*<name>*.py"` instead of running the test runner across the repo.\n\n### 4. Immediate Patch Submission\n- Once your targeted test passes:\n  1. Call the `submit_patch` tool immediately. It is a tool, not a shell command: never run `submit_patch` through `run_command`.\n  2. Verify `patch_size > 0` and `files_changed > 0`.\n  3. Output a short summary of the fix to end the session.\n\n## Anti-Patterns to Avoid\n- **NEVER modify, create, or delete test files** (`*_test.py`, `test_*.py`, or anything under `tests/`). All changes must be to source implementation files. Modifying tests results in an automatic evaluation failure.\n- **NEVER run full repository test suites** (e.g., bare `pytest` or `pytest .`) — always specify the exact test file path.\n- **NEVER attempt to fix or repair existing tests or pre-existing repository breakages** — your task is strictly to implement the fix for the reported issue in source code.\n- **NEVER search outside `/workspace`** for source files or packages (e.g., `/usr/local/lib/`, `/wheels/`, `/opt/`). All repository code and test dependencies are pre-installed. If `ModuleNotFoundError` occurs during test runs, focus on fixing code under `/workspace`, not looking for missing system packages.\n- Do NOT spend turns running broad exploratory searches if the file path or symbol is obvious.\n- Do NOT refactor or reformat unrelated functions or files.\n- Do NOT conclude without submitting a non-empty patch (`patch_size > 0`). Every task requires concrete source modifications. Concluding that the codebase is already clean without making changes is an anti-pattern.\n')
TOOLS = '[{"type": "function", "function": {"name": "run_command", "description": "Execute a shell command inside the repository sandbox.\\n\\nYou can run any shell command (Python scripts, tests, git commands, etc.).\\nThe command runs in the repository workspace. No network access.\\n\\nArgs:\\n    command: Shell command to execute (e.g., \\"pytest tests/\\", \\"python3 script.py\\").", "parameters": {"type": "object", "properties": {"command": {"type": "string"}}, "required": ["command"]}}}, {"type": "function", "function": {"name": "write_file", "description": "Create or overwrite a file in the workspace.\\n\\nArgs:\\n    filepath: Relative path to the file to create or overwrite.\\n    content: Full content of the file.", "parameters": {"type": "object", "properties": {"filepath": {"type": "string"}, "content": {"type": "string"}}, "required": ["filepath", "content"]}}}, {"type": "function", "function": {"name": "get_status", "description": "Check active budget details (time, tool calls) and active patch details.", "parameters": {"type": "object", "properties": {}, "required": []}}}, {"type": "function", "function": {"name": "submit_patch", "description": "Capture the current working tree modifications as the agent\'s submission.\\n\\nThis generates a unified git diff against the baseline commit. The agent\\ncan submit multiple times; only the final submission is evaluated.", "parameters": {"type": "object", "properties": {}, "required": []}}}, {"type": "function", "function": {"name": "get_code_neighbors", "description": "Discover structural code graph neighbors (callers and callees) for a given code node.\\n\\nArgs:\\n    node: Dotted symbol path or suffix of the function, method, or class node (e.g. \'pkg.module.Class.method\', \'Class.method\', or \'parse_request\').\\n    edge_type: Optional edge relation filter (e.g. \'calls\', case-insensitive).\\n    max_neighbors: Maximum number of neighbor nodes to return (default: 50).\\n\\nReturns:\\n    Dictionary with list of neighbor node names and count.", "parameters": {"type": "object", "properties": {"node": {"type": "string"}, "edge_type": {"type": "string"}, "max_neighbors": {"type": "integer"}}, "required": ["node"]}}}, {"type": "function", "function": {"name": "search_similar_code", "description": "Find semantically similar code functions and classes using precomputed graph embeddings.\\n\\nArgs:\\n    query: Dotted symbol path or suffix of a function/method/class in the repository (e.g. \'pkg.module.Class.method\', \'Class.method\', or \'func_name\') to find similar code for. Falls back to lexical keyword matching if no symbol matches.\\n    k: Number of most similar code nodes to return (default: 10).\\n\\nReturns:\\n    Dictionary containing matching node names, code snippets, and similarity scores.", "parameters": {"type": "object", "properties": {"query": {"type": "string"}, "k": {"type": "integer"}}, "required": ["query"]}}}, {"type": "function", "function": {"name": "get_code_subgraph", "description": "Extract the relationship graph (nodes and connecting edges) for a focal set of code elements.\\n\\nArgs:\\n    nodes: List of dotted symbol paths or suffix names (e.g. [\'pkg.mod.Class.method\', \'helper_fn\']) to include in the induced subgraph.\\n\\nReturns:\\n    Dictionary detailing the subgraph nodes and connecting directed edges.", "parameters": {"type": "object", "properties": {"nodes": {"type": "array", "items": {"type": "string"}}}, "required": ["nodes"]}}}]'
main(SUB, json.loads(TOOLS))
